INSERT INTO webami_products VALUES(179746,'frail words collapse|as i lay dying|as i lay dying|lp','Frail Words Collapse','As I Lay Dying','As I Lay Dying','LP','MTB161881.1','039841618815',25.46000000000000085,25.46000000000000085,'45774614','2026-11-10 23:51:29','2026-11-10 23:51:29','/03984161881','(Colored Vinyl, Orange, Smoke)',0,'Limited orange smoke colored vinyl LP pressing. Reissue. Frail Words Collapse is the second studio album by metalcore band As I Lay Dying, originally released in 2003. The album features the band''s signature song "Forever".','1/23/2026',0.589999999999999969,'lb','https://mediacdn.aent-m.com/prod-img/500/72/4478672-3499037.jpg?ae=4621895153','Rock,Heavy Metal');
