INSERT INTO webami_products VALUES(179765,'rude boy import|zeds dead|zeds dead|lp','Rude Boy [Import]','Zeds Dead','Zeds Dead','LP','IMT0329813.1','044003298132',19.39000000000000056,19.39000000000000056,'44268732','2026-11-10 23:51:33','2026-11-10 23:51:33','/04400329813','(Canada - Import)',0,NULL,'12/8/2023',0.5999999999999999778,'lb','https://mediacdn.aent-m.com/prod-img/500/00/4324500-3559843.jpg?ae=4621895153','Rock');
INSERT INTO webami_products VALUES(179766,'blackout|dropkick murphys|dropkick murphys|lp','Blackout','Dropkick Murphys','Dropkick Murphys','LP','HLCT80446.1','045778044610',15.40000000000000035,15.40000000000000035,'09326675','2026-11-10 23:51:33','2026-11-10 23:51:42','/045778044610',NULL,0,'Legendary punk band''s 2003 album is everything good punk stands for, featuring the Dropkicks'' signature Celtic-infused style and balls to the walls attitude.','6/10/2003',0.5500000000000000444,'lb','https://media.aent-m.com/graphics/items/sdimages/c/500/7/2/4/9/509427.jpg?ae=4621895153','Punk');
