INSERT INTO webami_products VALUES(179897,'a very jonas christmas movie original soundtrack|jonas brothers|jonas brothers|lp','A Very Jonas Christmas Movie (Original Soundtrack)','Jonas Brothers','Jonas Brothers','LP','HWD205922.1','050087590352',22.78999999999999915,22.78999999999999915,'45567261','2026-11-10 23:51:59','2026-11-10 23:51:59','/05008759035','(Colored Vinyl, Green)',0,'Jonas Brothers - A Very Jonas Christmas Movie (Original Soundtrack) - Vinyl Celebrate the season with A Very Jonas Christmas Movie Original Soundtrack, featuring 7 all-new songs from the Jonas Brothers. From London to New York, Nick, Joe, and Kevin bring the holiday spirit to life with original tracks and fan-favorite hits. A must-have for every Jonas fan, this festive green vinyl will keep your holidays merry and bright.','11/14/2025',0.5799999999999999601,'lb','https://mediacdn.aent-m.com/prod-img/500/35/4461535-3475699.jpg?ae=4621895153','Xmas Vocal');
INSERT INTO webami_products VALUES(179898,'toy story 5 original soundtrack|randy newman|randy newman|lp','Toy Story 5 (Original Soundtrack)','Randy Newman','Randy Newman','LP','DSN247079.1','050087605957',30.55000000000000071,30.55000000000000071,'46400819','2026-11-10 23:51:59','2026-11-10 23:51:59','/05008760595','(Picture Disc Vinyl)',0,'Randy Newman - Disney And Pixar''s Toy Story 5 (Original Soundtrack) - Vinyl 2xLP The toys are back in Disney and PixarΓÇÖs ΓÇ£Toy Story 5,ΓÇ¥ and this time itΓÇÖs Toy meets Tech. Woody (voice of Tom Hanks), Buzz Lightyear (voice of Tim Allen), Jessie (voice of Joan Cusack) and the rest of the gang''s jobs are challenged when they come face-to-face with Lilypad (voice of Greta Lee), a brand-new tablet device that arrives with her own disruptive ideas about what is best for their kid, Bonnie. The soundtrack features an original song from Grammy┬« Award-winning artist Taylor Swift titled, ΓÇ£I Knew It, I Knew You,ΓÇ¥ and an all-new original score from Academy┬« Award-winning composer and Disney Legend Randy Newman.','9/25/2026',1.489999999999999992,'lbs','https://mediacdn.aent-m.com/prod-img/500/17/4525117-3697981.jpg?ae=4621895153','Soundtrack');
