INSERT INTO webami_products VALUES(179970,'l a woman import|the doors|the doors|lp','L.A. Woman [Import]','The Doors','The Doors','LP','WETL9603281.1','075596032810',19.39000000000000056,19.39000000000000056,'20932916','2026-11-10 23:52:09','2026-11-10 23:52:09','/07559603281',NULL,0,'180-gram black vinyl reissue. The sixth studio album by the American rock band. Features the singles ''Love Her Madly'' and ''Riders on the Storm''.','10/13/2003',0.5600000000000000533,'lb','https://media.aent-m.com/graphics/items/sdimages/c/500/8/5/8/0/590858.jpg?ae=4621895153','Rock');
