INSERT INTO webami_products VALUES(180045,'fortitude|gojira|gojira|lp','Fortitude','Gojira','Gojira','LP','ATL859260.1','075678592607',22.07000000000000028,22.07000000000000028,'45656293','2026-11-10 23:52:20','2026-11-10 23:52:20','/07567859260','(Colored Vinyl, Gray, Brown, Splatter)',0,'Recorded and Produced by Joe Duplantier at Silver Cord Studio - Gojira''s Ridgewood, Queens, headquarters - and mixed by Andy Wallace (Nirvana, Rage Against the Machine), ''Fortitude'' is a collection of songs urging humanity to imagine a new world - and then make it happen. The band initially laid the foundation for ''Fortitude'' in 2020 with the surprise release of the single ''Another World''.','11/28/2025',0.5500000000000000444,'lb','https://mediacdn.aent-m.com/prod-img/500/66/4469766-3510598.jpg?ae=4621895153','Rock,Heavy Metal');
