INSERT INTO webami_products VALUES(180083,'slipknot 25th anniversary edition|slipknot|slipknot|lp','Slipknot (25th Anniversary Edition) [Explicit Content]','Slipknot','Slipknot','LP','RRD611643.1','075678611643',31.51999999999999958,31.51999999999999958,'45362378','2026-11-10 23:52:28','2026-11-10 23:52:28','/07567861164','(Parental Advisory Explicit Lyrics, 140 Gram Vinyl, Anniversary Edition, Gatefold LP Jacket)',0,'SLIPKNOT - Slipknot (25th Anniversary Edition) - 25th anniversary edition of Slipknot''s self-titled debut with unreleased demos and alternative mixes. Standard all-retail vinyl. 140g, 2LP black vinyl, gatefold jacket, dress sleeves & marketing sticker.','9/5/2025',1.129999999999999893,'lbs','https://mediacdn.aent-m.com/prod-img/500/17/4443317-3445974.jpg?ae=4621895153','Heavy Metal');
