INSERT INTO webami_products VALUES(180098,'take this to your grave 20th anniversary|fall out boy|fall out boy|lp','Take This To Your Grave (20th Anniversary)','Fall Out Boy','Fall Out Boy','LP','FUEL613425.1','075678613425',22.51000000000000157,22.51000000000000157,'43967339','2026-11-10 23:52:30','2026-11-10 23:52:30','/07567861342','(Colored Vinyl, Blue, Anniversary Edition)',0,'Take This to Your Grave (20th Anniversary) Fall Out Boy - Celebrate the 20th anniversary of Fall Out Boy''s debut album ''Take This to Your Grave'' with this special limited-edition release featuring two never released demos. Pressed on Blue Jay Vinyl.','12/15/2023',0.5300000000000000266,'lb','https://mediacdn.aent-m.com/prod-img/500/06/4269606-3075026.jpg?ae=4621895153','Rock');
INSERT INTO webami_products VALUES(180099,'so much for stardust|fall out boy|fall out boy|lp','So Much (For) Stardust','Fall Out Boy','Fall Out Boy','LP','FUEL863069.1','075678630699',22.51000000000000157,22.51000000000000157,'43273188','2026-11-10 23:52:30','2026-11-10 23:52:30','/07567863069',NULL,0,'Fall Out Boy - So Much (For) Stardust - LP GRAMMY Award-nominated and multi-platinum selling rock band Fall Out Boy announced that their eighth studio album So Much (For) Stardust will arrive March 24, 2023. So Much (For) Stardust will be released on Fueled By Ramen/Elektra - Fall Out Boy''s first album with the label since their 2003 debut album Take This to Your Grave, which celebrates it''s 20th anniversary on May 6.','3/24/2023',0.6800000000000000488,'lb','https://mediacdn.aent-m.com/prod-img/500/02/4177902-2940405.jpg?ae=4621895153','Rock');
INSERT INTO webami_products VALUES(180100,'cry baby|melanie martinez|melanie martinez|lp','Cry Baby','Melanie Martinez','Melanie Martinez','LP','ATL677280.1','075678639494',29.6700000000000017,29.6700000000000017,'43250561','2026-11-10 23:52:30','2026-11-10 23:52:30','/07567863949','(Deluxe Edition)',0,'Double vinyl LP pressing. Melanie Martinez''s 2017 double-platinum debut album Cry Baby has now been expanded to a two LP set featuring the full deluxe album tracking listing. Three songs ("Play Date", "Teddy Bear" and "Cake") have been added to the album''s original 13 tracks while the enclosed booklet has expanded to 20 pages featuring new illustrations.','2/17/2023',1.659999999999999921,'lbs','https://mediacdn.aent-m.com/prod-img/500/38/4173638-2935090.jpg?ae=4621895153','Pop');
