INSERT INTO webami_products VALUES(180210,'greatest hits|the ramones|the ramones|lp','Greatest Hits','The Ramones','The Ramones','LP','RHI728700.1','081227804855',19.64000000000000056,19.64000000000000056,'45730528','2026-11-10 23:52:49','2026-11-10 23:52:49','/08122780485','(Limited Edition, Colored Vinyl, Brick & Mortar Exclusive, Black Ice)',0,'Ramones Greatest Hits / This 1-LP compilation of Ramones sub-2 minute zingers (for the most part) collects highlights from the band''s extensive career from their first release in 1976 through 1994. Includes everything you''d want and expect from "Blitzkreig Bop" and "Sheena Is A Punk Rocker" to "Pinhead" and "Wart Hog."','1/9/2026',0.5400000000000000355,'lb','https://mediacdn.aent-m.com/prod-img/500/15/4474415-3493248.jpg?ae=4621895153','Rock');
