INSERT INTO webami_products VALUES(180258,'rent original soundtrack|various artists|various artists|lp','Rent (Original Soundtrack)','Various Artists','Various Artists','LP','RHI49455.1','081227809157',31.51999999999999958,31.51999999999999958,'45576676','2026-11-10 23:52:59','2026-11-10 23:52:59','/08122780915','(Clear Vinyl, White, Brick & Mortar Exclusive)',0,'For the first time ever and in celebration of the 20th anniversary of the film, Rent (Original Motion Picture Soundtrack) is coming to vinyl! Based on the 1996 award-winning and beloved musical produced by Jonathan Larson, the broadway to film soundtrack takes you on the journey of struggle, resilience, and community in the midst of the AIDS epidemic in New York City. The album contains 6 of the original 8 Broadway cast members and features the hits "Seasons of Love" and "Take Me Or Leave Me." Milky Clear Vinyl & Translucent Red','11/27/2025',1.060000000000000053,'lbs','https://mediacdn.aent-m.com/prod-img/500/65/4462365-3460985.jpg?ae=4621895153','Soundtrack');
