INSERT INTO webami_products VALUES(180473,'californication|red hot chili peppers|red hot chili peppers|lp','Californication','Red Hot Chili Peppers','Red Hot Chili Peppers','LP','WB726701.1','093624843276',32.14999999999999858,32.14999999999999858,'44451745','2026-11-10 23:53:56','2026-11-10 23:53:56','/09362484327',NULL,0,'Double colored vinyl LP pressing. Red Hot Chili Peppers released their seventh studio album, Californication. The album was produced by Rick Rubin and marked the return of guitarist John Frusciante. To mark the 25th anniversary of this landmark album, a limited edition double vinyl is being released - with one LP pressed on red vinyl and one LP on ocean blue vinyl.','7/26/2024',0.9000000000000000222,'lb','https://mediacdn.aent-m.com/prod-img/500/71/4351971-3221184.jpg?ae=4621895153','Rock');
