INSERT INTO webami_products VALUES(180835,'run rose run|dolly parton|dolly parton|lp','Run Rose Run','Dolly Parton','Dolly Parton','LP','BTTR001.1','192641820007',13.18999999999999951,13.18999999999999951,'42417163','2026-11-10 23:54:39','2026-11-10 23:54:39','/19264182000',NULL,0,'Vinyl LP pressing. Country/Bluegrass album, Run, Rose, Run that will be released along with a novel co-written with the famed author, James Patterson, sharing the title Run Rose Run. The 12 songs were inspired by the book storyline and feature Country and Bluegrass artists; Joe Nichols, Rhonda Vincent, The Issacs, and Dailey & Vincent. Dolly & James will be doing book and album promotions together - presenting a unique co-marketing opportunity. Black LP','4/1/2022',0.660000000000000031,'lb','https://mediacdn.aent-m.com/prod-img/500/28/4057128-2788805.jpg?ae=4621895153','Country');
