INSERT INTO webami_products VALUES(180898,'fear inoculum|tool|tool|lp','Fear Inoculum','Tool','Tool','LP','RCA50201.1','194399502013',49.46000000000000085,49.46000000000000085,'42806219','2026-11-10 23:54:41','2026-11-10 23:54:41','/19439950201','(180 Gram Vinyl, Gatefold LP Jacket, Poster)',1,'Fear Inoculum is the Grammy award winning masterpiece from Tool. Following the release of the limited edition single pressing ultra deluxe 5 disc vinyl box set, this critically acclaimed album is available now as a 3 disc 180 gram set, that features new artwork in a triple gatefold jacket and an exclusive poster. Tool members include drummer Danny Carey, guitarist Adam Jones, bassist Justin Chancellor and vocalist Maynard James Keenan. TOOL / FEAR INOCULUM','8/5/2022',1.780000000000000026,'lbs','https://mediacdn.aent-m.com/prod-img/500/45/4112145-2851880.jpg?ae=4621895153','Rock');
