INSERT INTO webami_products VALUES(180968,'christmas in the heart|bob dylan|bob dylan|lp','Christmas In The Heart','Bob Dylan','Bob Dylan','LP','SNYL878968.1','196587896812',19.03999999999999915,19.03999999999999915,'43730216','2026-11-10 23:54:45','2026-11-10 23:54:45','/19658789681','(150 Gram Vinyl)',0,'Bob Dylan''s Christmas In The Heart was released on October 13, 2009 by Columbia Records. The album, being Dylan''s 34th studio album, is his first and only Christmas album comprised of a collection of hymns, carols, and popular Christmas songs. The album includes "Must Be Santa, " "Little Drummer Boy, " and "Here Comes Santa Claus."','10/6/2023',0.5799999999999999601,'lb','https://mediacdn.aent-m.com/prod-img/500/58/4241758-3048664.jpg?ae=4621895153','Xmas Vocal');
