INSERT INTO webami_products VALUES(181060,'magpie|peach pit|peach pit|lp','Magpie','Peach Pit','Peach Pit','LP','CLBI81182.1','198028118217',22.30000000000000071,22.30000000000000071,'44596521','2026-11-10 23:54:49','2026-11-10 23:54:49','/19802811821','(Clear Vinyl, Green)',0,'Magpie, the fourth studio album from Peach Pit is due out October 25th. The album was written and recorded in the band''s hometown of Vancouver, BC. Single disc vinyl, standard jacket, printed sleeve, with poster. COLOR: Clear Mint','10/25/2024',0.6300000000000000044,'lb','https://mediacdn.aent-m.com/prod-img/500/85/4368485-3269488.jpg?ae=4621895153','Rock');
