INSERT INTO webami_products VALUES(181117,'sos deluxe lana|sza|sza|lp','Sos Deluxe: Lana [Explicit Content]','SZA','SZA','LP','RCA289201.1','198028920117',63.28999999999999915,63.28999999999999915,'45296369','2026-11-10 23:54:51','2026-11-10 23:54:51','/19802892011','(Parental Advisory Explicit Lyrics)',0,'Limited four green vinyl LP pressing. SOS Deluxe: LANA finds the singer-songwriter even more candid than it''s predecessor. Across the collection''s now-42 tracks, SZA is vulnerable as she confesses her weaknesses and acknowledges her flaws, all while on her journey to find peace.','7/25/2025',1.889999999999999903,'lbs','https://mediacdn.aent-m.com/prod-img/500/96/4436996-3408528.jpg?ae=4621895153','Soul/R & B');
