INSERT INTO webami_products VALUES(181148,'faith|george michael|george michael|lp','Faith','George Michael','George Michael','LP','SNYL293166.1','198029316612',33.71000000000000085,33.71000000000000085,'45805486','2026-11-10 23:54:52','2026-11-10 23:54:52','/19802931661','(Limited Edition, Colored Vinyl)',0,'Double purple marbled vinyl LP pressing. Few albums have defined an era and redefined a generation of pop music quite like Faith, George Michael''s groundbreaking 1987 debut solo album. Written, arranged, produced, and performed almost entirely by George, ''Faith'' includes the hit singles ''Faith'', ''Father Figure'', ''One More Try'' and ''Monkey''. Now available on vinyl for the first time in over a decade, this limited edition 10 track 2LP marble vinyl features ''I Want Your Sex- Pts. 1, 2 & 3, The Monogamy Mix.''','2/20/2026',1.439999999999999947,'lbs','https://mediacdn.aent-m.com/prod-img/500/99/4479599-3505815.jpg?ae=4621895153','Vocal');
INSERT INTO webami_products VALUES(181149,'i feel the everblack festering within me|lorna shore|lorna shore|lp','I Feel The Everblack Festering Within Me','Lorna Shore','Lorna Shore','LP','CEN932791.1','198029327915',28.37000000000000099,28.37000000000000099,'45219412','2026-11-10 23:54:52','2026-11-10 23:54:52','/19802932791','(Indie Exclusive, Colored Vinyl, Light Blue, Gatefold LP Jacket)',0,'I Feel The Everblack Festering Within Me - Lorna Shore / I Feel the Everblack Festering Within Me is the fifth studio album by deathcore band Lorna Shore. It was released on September 12, 2025, through Century Media Records and was produced by Josh Schroeder.','9/12/2025',1.239999999999999992,'lbs','https://mediacdn.aent-m.com/prod-img/500/50/4430050-3399099.jpg?ae=4621895153','Rock,Heavy Metal');
