INSERT INTO webami_products VALUES(181213,'cloud 9 megan s signature pink vinyl|megan moroney|megan moroney|lp','Cloud 9: Megan''s Signature Pink Vinyl [Explicit Content]','Megan Moroney','Megan Moroney','LP','CLBI299956.1','198029995619',25.21000000000000085,25.21000000000000085,'45712463','2026-11-10 23:54:55','2026-11-10 23:54:55','/19802999561','(Parental Advisory Explicit Lyrics, Colored Vinyl, Pink, Poster, Gatefold LP Jacket)',0,'Megan Moroney - Cloud 9: Megan''s Signature Pink Vinyl Cloud 9 is the third studio album from MULTI-PLATINUM phenomenon Megan Moroney. Building on the massive momentum of 2024ΓÇÖs era-defining Am I Okay, the Country superstarΓÇÖs latest LP features her Billboard Hot 100 smash ΓÇ£6 Months LaterΓÇ¥ and hit ballad ΓÇ£Beautiful Things.ΓÇ¥ Packaging includes a gatefold jacket with 24x36ΓÇ¥ poster on MeganΓÇÖs Signature Pink vinyl.','2/20/2026',1.469999999999999974,'lbs','https://mediacdn.aent-m.com/prod-img/500/10/4472610-3727509.jpg?ae=4621895153','Country');
