INSERT INTO webami_products VALUES(181279,'talk is cheap|fight from within|fight from within|lp','Talk Is Cheap [Explicit Content]','Fight From Within','Fight From Within','LP','LBGP250.1','198704781810',15.18999999999999951,15.18999999999999951,'45606618','2026-11-10 23:54:58','2026-11-10 23:54:58','/19870478181','(Parental Advisory Explicit Lyrics, Colored Vinyl, Red)',0,'This is the much anticipated first full album release from Metalcore''s new rising stars Fight From Within. Their authentic, don''t give a f%8k attitude is winning over the metal community. Proven in their rapidly rising numbers across platforms, this is a band to watch. Talk Is Cheap is the first of many releases for this young band out of upper state NY.','1/9/2026',0.589999999999999969,'lb','https://mediacdn.aent-m.com/prod-img/500/12/4465312-3463778.jpg?ae=4621895153','Heavy Metal');
