INSERT INTO webami_products VALUES(181313,'peppa pig greatest hits|peppa pig|peppa pig|lp','Peppa Pig Greatest Hits','Peppa Pig','Peppa Pig','LP','HARO801932.1','199066801932',23.76000000000000156,23.76000000000000156,'45123122','2026-11-10 23:55:00','2026-11-10 23:55:00','/19906680193','(Colored Vinyl, Pink)',0,'Limited pink colored vinyl LP pressing. Peppa Pig PEPPA PIG GREATEST HITS Peppa Pig''s Greatest Hits'' brings together sixteen of Peppa''s biggest hits including ''Piggle Wiggle'' and ''Bing Bong Zoo'' on an oinktastic pink color LP.','6/6/2025',0.5400000000000000355,'lb','https://mediacdn.aent-m.com/prod-img/500/02/4421602-3383810.jpg?ae=4621895153','Children''s,Children''s Video');
INSERT INTO webami_products VALUES(181314,'frizzle fry|primus|primus|lp','Frizzle Fry','Primus','Primus','LP','PRWN16135.1','199066130773',19.39000000000000056,19.39000000000000056,'44998639','2026-11-10 23:55:00','2026-11-10 23:55:00','/19906613077','(Clear Vinyl, White, Purple, Anniversary Edition)',0,'Limited purple / clear split colored vinyl LP pressing. Happy 35th Birthday to Frizzle Fry. In celebration, the album is available for the first time on a clear/purple split vinyl.','6/6/2025',0.5799999999999999601,'lb','https://mediacdn.aent-m.com/prod-img/500/88/4409788-3330888.jpg?ae=4621895153','Rock');
