INSERT INTO webami_products VALUES(181381,'age aint nothing but a number|aaliyah|aaliyah|lp','Age Aint Nothing But A Number','Aaliyah','Aaliyah','LP','SNYL841451.1','199584145112',20.12999999999999901,20.12999999999999901,'46158345','2026-11-10 23:55:05','2026-11-10 23:55:05','/19958414511',NULL,0,'Age Ain''t Nothing But A Number by Aaliyah / Aaliyah''s groundbreaking debut album Age Ain''t Nothing But A Number returns on classic black vinyl. First released in 1994, this record introduced the world to Aaliyah''s smooth, confident sound. Rediscover the sensual grooves, smooth vocals, and timeless hits that defined an era, including "Age Ain''t Nothing But a Number," "Back & Forth," and the unforgettable "At Your Best (You Are Love)." Also includes the bonus international track "The Thing I Like" which also appeared on the A Low Down Dirty Shame soundtrack.','5/15/2026',0.08999999999999999667,'lb','https://mediacdn.aent-m.com/prod-img/500/41/4507941-3570126.jpg?ae=4621895153','Soul/R & B');
