INSERT INTO webami_products VALUES(181431,'timeless|prince|prince|lp','Timeless','Prince','Prince','LP','SNYL845329.1','199584532912',18.67000000000000171,18.67000000000000171,'46340993','2026-11-10 23:55:07','2026-11-10 23:55:07','/19958453291',NULL,0,'PRINCE / TIMELESS Timeless is a brand-new 10-track compilation featuring rare and unreleased studio recordings from Prince''s legendary vault. This unprecedented album encompasses tracks spanning every phase of Prince''s illustrious career, from 1977 to 2016. The project has been meticulously mastered by Grammy-nominated engineer and producer Chris James, a former Prince engineer whose notable credits include HITnRUN Phase Two, Art Official Age, and Plectrumelectrum. Timeless is now available on black vinyl, providing profound insights into Prince''s creative process and musical evolution.','8/28/2026',0.6099999999999999867,'lb','https://mediacdn.aent-m.com/prod-img/500/93/4519993-3701113.jpg?ae=4621895153','Soul/R & B');
