INSERT INTO webami_products VALUES(181453,'lovers rock d2c indie exclusive|sade|sade|lp','Lovers Rock   (D2C/ Indie Exclusive)','Sade','Sade','LP','SNYL847022.1','199584702216',25.21000000000000085,25.21000000000000085,'46608307','2026-11-10 23:55:09','2026-11-10 23:55:09','/19958470221','(Indie Exclusive, Limited Edition, Clear Vinyl)',0,'Sade - Lovers Rock / The Grammy Award winning Lovers Rock was released in 2000 and went on to become a multi-million-selling, multi-platinum certified album with huge global success. The album, the first after an 8-year hiatus, includes key tracks ''By Your Side'', ''King Of Sorrow'' and the eponymous ''Lovers Rock''. This limited-edition LP is pressed on clear vinyl.','11/13/2026',0.5400000000000000355,'lb','https://mediacdn.aent-m.com/prod-img/500/25/4543725-3719612.jpg?ae=4621895153','Soul/R & B');
