INSERT INTO webami_products VALUES(181526,'dinner party|niall horan|niall horan|lp','Dinner Party [Explicit Content]','Niall Horan','Niall Horan','LP','CAP241553.1','199957416795',22.78999999999999915,22.78999999999999915,'46111296','2026-11-10 23:55:12','2026-11-10 23:55:12','/19995741679','(Parental Advisory Explicit Lyrics, Indie Exclusive, Clear Vinyl, Alternate Cover)',0,'Niall Horan returns with his fourth solo album, ΓÇÿDinner Party.ΓÇÖ Calling it ΓÇ£a thank you to the past and a hello to the present,ΓÇ¥ Niall delivers 12 new tracks shaped by ΓÇ£love, intimacy, fear, loss, hope and dreams.ΓÇ¥ Cinematic yet organic, ΓÇÿDinner PartyΓÇÖ invites listeners to take a seat at the table and share in the warmth, wit and sincerity that define the album.','6/5/2026',0.5500000000000000444,'lb','https://mediacdn.aent-m.com/prod-img/500/48/4503348-3597718.jpg?ae=4621895153','Vocal');
