INSERT INTO webami_products VALUES(181543,'another level|blackstreet|blackstreet|lp','Another Level','Blackstreet','Blackstreet','LP','ISC244698.1','199957661355',26.42999999999999972,26.42999999999999972,'46433060','2026-11-10 23:55:13','2026-11-10 23:55:13','/19995766135',NULL,0,'Celebrating the 30th Anniversary of Another Level. This is Blackstreet''s second studio album, released in 1996 through Interscope Records. The album represents the group at their commercial peak, blending smooth R&B harmonies with hip-hop production and a polished, radio-ready sound. Another Level was a major commercial success, earning multi-platinum certification and solidifying Blackstreet as one of the leading R&B groups of the 1990s. The album played a key role in shaping the fusion of R&B and hip-hop that defined the era.','9/4/2026',1.110000000000000098,'lbs','https://mediacdn.aent-m.com/prod-img/500/55/4528155-3670505.jpg?ae=4621895153','Soul/R & B');
