INSERT INTO webami_products VALUES(181651,'adult contemporary|chromeo|chromeo|lp','Adult Contemporary','Chromeo','Chromeo','LP','BGRT922011.1','4050538922011',27.69000000000000127,27.69000000000000127,'44066932','2026-11-10 23:55:17','2026-11-10 23:55:17','/405053892201',NULL,0,'Adult Contemporary explicit_lyrics Chromeo / Chromeo''s 6th Studio Album, Adult Contemporary, 2LP Black Vinyl, Gatefold Jacket.','2/16/2024',1.120000000000000107,'lbs','https://mediacdn.aent-m.com/prod-img/500/75/4287975-3092076.jpg?ae=4621895153','Electronic');
INSERT INTO webami_products VALUES(181652,'the number of the beast 2015 remaster|iron maiden|iron maiden|lp','The Number of the Beast [2015 Remaster]','Iron Maiden','Iron Maiden','LP','BMTP166710.1','4050538906417',19.87999999999999901,19.87999999999999901,'44911782','2026-11-10 23:55:17','2026-11-10 23:55:17','/405053890641','(180 Gram Vinyl, Remastered)',0,'Iron Maiden - "The Number of the Beast" [2015 Remaster] [180gram Heavy Vinyl LP] Their first release with vocalist Bruce Dickinson, The Number of the Beast was Iron Maiden''s first album to hit the Top 40 in the US and be certified platinum. Released in 1982, it features the classic tracks, "Run to the Hills," "The Number of the Beast," "Hallowed Be Thy Name," and more. The 2015 remaster is available on vinyl for the first time. BMG Rights Management; BMG; Metal; Catalog 180-Gram Reissue LP.','2/14/2025',0.660000000000000031,'lb','https://mediacdn.aent-m.com/prod-img/500/80/4400080-3726126.jpg?ae=4621895153','Heavy Metal');
INSERT INTO webami_products VALUES(181653,'donkey punch the night|puscifer|puscifer|lp','Donkey Punch The Night','Puscifer','Puscifer','LP','BGRT245538.1','4050538887129',20.12999999999999901,20.12999999999999901,'46379382','2026-11-10 23:55:17','2026-11-10 23:55:17','/405053888712','(Extended Play)',0,'The 2013 EP ''Donkey Punch The Night'' from Puscifer (featuring Maynard James Keenan of Tool and A Perfect Circle). This album features covers of Queen''s "Bohemian Rhapsody" and Accept''s "Balls to the Wall," plus more! Available on classic 12" vinyl.','9/25/2026',0.5,'lb','https://mediacdn.aent-m.com/prod-img/500/21/4523421-3737642.jpg?ae=4621895153','Rock');
