INSERT INTO webami_products VALUES(181686,'home sweet home|motley crue|motley crue|lp','Home Sweet Home','Motley Crue','Motley Crue','LP','BGRT205872.1','4099964158779',22.78999999999999915,22.78999999999999915,'45570087','2026-11-10 23:55:21','2026-11-10 23:55:21','/409996415877','(RSD Exclusive, Extended Play, Picture Disc Vinyl, Anniversary Edition)',0,'M├╢tley Cr├╝e''s iconic power ballad, "Home Sweet Home," released on limited-edition picture disc 12" vinyl for Record Store Day. Celebrate the 40th anniversary of one of rock''s most legendary anthems. Includes 6 versions, including "Home Sweet Home" (original), "Home Sweet Home" feat. Dolly Parton and the Top 40 charting "Home Sweet Home ''91"','11/27/2025',0.5999999999999999778,'lb','https://mediacdn.aent-m.com/prod-img/500/96/4461796-3459463.jpg?ae=4621895153','Rock');
INSERT INTO webami_products VALUES(181687,'from the beginning|motley crue|motley crue|lp','From The Beginning','Motley Crue','Motley Crue','LP','BGRT186309.1','4099964161793',24.73000000000000042,24.73000000000000042,'45304347','2026-11-10 23:55:21','2026-11-10 23:55:21','/409996416179',NULL,0,'M├╢tley Cr├╝e - "From The Beginning" [2 LP] From The Beginning spans four decades of Cr├╝e anthems, kicking off with their first global single and MTV video "Live Wire" and winding through the years to 2024''s Top 5 rock smash "Dogs Of War." In between are the hits and fan favorites that shaped the rock genre and a generation, including "Kickstart My Heart," "Dr. Feelgood," "Girls, Girls, Girls," "Shout at the Devil," "Smokin'' In The Boys Room," "Wild Side," and many more. Includes a stunning new version of the band''s revered classic, "Home Sweet Home," reimagined as a heartfelt duet with none other than globally beloved superstar Dolly Parton. 2 LP set features 21 tracks.','9/12/2025',1.139999999999999902,'lbs','https://mediacdn.aent-m.com/prod-img/500/61/4437761-3411813.jpg?ae=4621895153','Rock');
