INSERT INTO webami_products VALUES(181721,'songs about us|jason aldean|jason aldean|lp','Songs About Us','Jason Aldean','Jason Aldean','LP','BGRT227782.1','4099964217568',27.14999999999999858,27.14999999999999858,'45698200','2026-11-10 23:55:23','2026-11-10 23:55:23','/409996421756','(Poster)',0,'Double vinyl LP pressing. Includes poster. Jason Aldean enters a new chapter with the release of his 12th studio album, a landmark project featuring 20 brand-new songs that showcase the full scope of his artistry from hard-charging anthems built for the stage to the kind of honest, lived-in storytelling that has defined his career. This expansive collection underscores Aldean''s staying power and creative evolution, reaffirming why he remains one of country music''s most enduring and influential voices.','4/24/2026',1.310000000000000053,'lbs','https://mediacdn.aent-m.com/prod-img/500/65/4471565-3493052.jpg?ae=4621895153','Country');
