INSERT INTO webami_products VALUES(181727,'tree city sessions 3|dance gavin dance|dance gavin dance|lp','Tree City Sessions 3 [Explicit Content]','Dance Gavin Dance','Dance Gavin Dance','LP','RISE243001.1','4099964238976',32.25,32.25,'46182234','2026-11-10 23:55:23','2026-11-10 23:55:23','/409996423897','(Parental Advisory Explicit Lyrics, Colored Vinyl, Bonus Tracks)',0,'Double "Velaris" splatter color vinyl LP pressing. Featuring 12 bonus instrumental tracks on Disc 2. Sacramento rock virtuosos Dance Gavin Dance deliver the 3rd release in their Tree City Sessions series. As with previous releases, Tree City Sessions 3 sees the band re-recording new versions of previous Dance Gavin Dance songs, all featuring current vocalist Andrew Michael Wells.','6/19/2026',1.020000000000000017,'lbs','https://mediacdn.aent-m.com/prod-img/500/64/4510264-3575387.jpg?ae=4621895153','Rock');
