INSERT INTO webami_products VALUES(181778,'my neighbor totoro image album original soundtrack import|joe hisaishi|joe hisaishi|lp','My Neighbor Totoro: Image Album (Original Soundtrack) [Import]','Joe Hisaishi','Joe Hisaishi','LP','SGHI10014.1','4988008086010',28.12000000000000099,28.12000000000000099,'36701902','2026-11-10 23:55:26','2026-11-10 23:55:26','/498800808601','(Limited Edition)',0,'Limited vinyl LP pressing. Image album created with the concept of ''making songs which children really want and can sing out loud with their mouth widely opened.'' Including 10 songs + one instrumental. Song : Azumi Inoue, Joe Hisaishi, Kumiko Mori, Taku Kitahara, Suginami Junior Chorus. With 16 pages of all the melody scores.','11/23/2018',0.7700000000000000177,'lb','https://mediacdn.aent-m.com/prod-img/500/39/3572539-3424960.jpg?ae=4621895153','Soundtrack');
