INSERT INTO webami_products VALUES(181781,'my neighbor totoro original soundtrack import|joe hisaishi|joe hisaishi|lp','My Neighbor Totoro (Original Soundtrack) [Import]','Joe Hisaishi','Joe Hisaishi','LP','SGHI10015.1','4988008086119',26.17999999999999972,26.17999999999999972,'36701919','2026-11-10 23:55:26','2026-11-10 23:55:26','/498800808611','(Limited Edition)',0,'Limited vinyl LP pressing. Soundtrack which you can feel warmth and enjoy Joe Hisaishi''s music to your heart''s content. Including ''Sanpo'' and ''My Neighbor Totoro.'' With liner notes and four pages of illustrations.','11/23/2018',0.660000000000000031,'lb','https://mediacdn.aent-m.com/prod-img/500/40/3572540-3424961.jpg?ae=4621895153','Soundtrack');
