INSERT INTO webami_products VALUES(181831,'black sands|bonobo|bonobo|lp','Black Sands','Bonobo','Bonobo','LP','NJAT140.1','5021392584188',25.62999999999999901,25.62999999999999901,'14922602','2026-11-10 23:55:31','2026-11-10 23:55:31','/502139258418',NULL,0,'Double vinyl LP pressing of this 2010 release. Simon Green (AKA Bonobo) returns with his fourth and finest album, Black Sands. Losing none of his epic emotionalism, his control of texture and color and his subtlety, Black Sands sees Green making some of his most contemporary-sounding music to date.','4/6/2010',0.959999999999999965,'lb','https://media.aent-m.com/graphics/items/sdimages/a/500/0/2/6/6/1616620.jpg?ae=4621895153','Nu-Jazz');
