INSERT INTO webami_products VALUES(181839,'x y|coldplay|coldplay|lp','X&Y','Coldplay','Coldplay','LP','ATL267382.1','5021732267382',32.14999999999999858,32.14999999999999858,'44507800','2026-11-10 23:55:32','2026-11-10 23:55:32','/502173226738','(Eco Vinyl)',0,'Double vinyl LP pressing. X&Y is the third studio album by Coldplay, originally released in 2005.','9/13/2024',0.9200000000000000399,'lb','https://mediacdn.aent-m.com/prod-img/500/83/4358683-3204498.jpg?ae=4621895153','Rock');
INSERT INTO webami_products VALUES(181840,'blackstar|david bowie|david bowie|lp','Blackstar','David Bowie','David Bowie','LP','RPLH239766.1','5021732397669',19.64000000000000056,19.64000000000000056,'46374004','2026-11-10 23:55:32','2026-11-10 23:55:32','/502173239766',NULL,0,'Vinyl LP pressing. Γÿà (Blackstar), Bowie''s final studio album, was released on his birthday, 8th January, 2016. Never one to stand still, Bowie worked with Donny McCaslin''s jazz quartet and longtime producer Tony Visconti, to create a challenging album of Art Rock with Jazz influences. Critically acclaimed, the album debuted at #1 in the UK and US as well as almost everywhere else in the world, and received three Grammy Awards.','7/24/2026',1.020000000000000017,'lbs','https://mediacdn.aent-m.com/prod-img/500/15/4523015-3675029.jpg?ae=4621895153','Rock');
INSERT INTO webami_products VALUES(181841,'live from the royal albert hall|dua lipa|dua lipa|lp','Live From The Royal Albert Hall','Dua Lipa','Dua Lipa','LP','WB727356.1','5021732410863',35.85999999999999944,35.85999999999999944,'44820220','2026-11-10 23:55:32','2026-11-10 23:55:32','/502173241086',NULL,0,'''Dua Lipa Live From The Royal Albert Hall'' features Dua''s greatest hits reimagined with The Heritage Orchestra, and a 14 person choir and 7 piece band. With spot gloss text detailing and a special die cut front cover, fans are able to swap the main album cover to one of 3 other images from the special showIncludes 2LPs, four exclusive images captured on the night and a 8 page booklet.','1/17/2025',1.149999999999999911,'lbs','https://mediacdn.aent-m.com/prod-img/500/30/4392230-3320098.jpg?ae=4621895153','Pop');
