INSERT INTO webami_products VALUES(181851,'holiday road||kesha records|7 single','Holiday Road',NULL,'Kesha Records','7" Single','KSHA577122.7','5021732577122',7.490000000000000213,7.490000000000000213,'45580017','2026-11-10 23:55:33','2026-11-10 23:55:33','/502173257712','(RSD Exclusive, Colored Vinyl)',0,'Pressed For The First Time Ever, Kesha''S 2024 Spotify Singles Holiday Cover Of Lindsey Buckingham''S "Holiday Road" Is Now Available On 7" Vinyl As A Record Store Day Black Friday Exclusive. The Release Marked A Milestone For The Track, Pushing It Into The Top 10 On A Billboard Chart For The First Time Ever, Reaching No. 6 On Hot Dance/Electronic Songs And No. 88 On The Billboard Ho╤é 100. The B-Side Features "A Very Merry Christmas From Kesha," An Unreleased Version Of "Have Yourself A Merry Little Christmas. " Originally Uploaded To Kesha''S Official Youtube Channel In 2010','11/27/2025',0.1600000000000000033,'lb','https://mediacdn.aent-m.com/prod-img/500/14/4462714-3460429.jpg?ae=4621895153','Vocal');
INSERT INTO webami_products VALUES(181852,'actual life 1 live|fred again|fred again|lp','Actual Life 1 (Live)','Fred Again...','Fred Again...','LP','ATL255175.1','5021732551757',39.28000000000000113,39.28000000000000113,'44962647','2026-11-10 23:55:33','2026-11-10 23:55:33','/502173255175','(RSD Exclusive, Colored Vinyl)',0,'For the first time ever, Fred will release his ''Actual Life'' piano live sessions on vinyl. There will be 3 vinyls limited to 5000 units each. They will be available as 1LP 140g 12" on Magnolia vinyl. Limited 5k each.','11/27/2025',0.6700000000000000399,'lb','https://mediacdn.aent-m.com/prod-img/500/32/4406032-3330125.jpg?ae=4621895153','Electronic');
