INSERT INTO webami_products VALUES(181871,'usb002|fred again|fred again|lp','USB002 [Explicit Content]','Fred Again','Fred Again','LP','ATL277471.1','5021732774712',39.28000000000000113,39.28000000000000113,'45640094','2026-11-10 23:55:34','2026-11-10 23:55:34','/502173277471','(Parental Advisory Explicit Lyrics)',1,'Fred Again. TITLE: USB Label: ATL/Atlantic - Fred again. Has released USB Volume 1- the first volume of his "Infinite" album project, which is now available as a limited vinyl drop. USB is an infinite, ever-evolving album that includes recent releases ''Baby Again, ''Rubmle'' with Skrillex & Flowdan, ''Jungle,'' ''leavemealone'' with Baby Keem and ''stayinit'' with Lil Yachty. It also features two new records; ''BerwynGesaffNeighbours'' and ''ItsNotREEAALLLLLLLL. '' (Fred again.. - USB002)','12/19/2025',1.09000000000000008,'lbs','https://mediacdn.aent-m.com/prod-img/500/88/4468188-3523765.jpg?ae=4621895153','Electronic');
