INSERT INTO webami_products VALUES(182079,'je ne regrette rien import|edith piaf|edith piaf|lp','Je Ne Regrette Rien [Import]','Edith Piaf','Edith Piaf','LP','IMT5011582.1','5060403742087',25.21000000000000085,25.21000000000000085,'27852378','2026-11-10 23:55:45','2026-11-10 23:55:45','/506040374208','(United Kingdom - Import)',0,'Double vinyl LP pressing. Piaf is a legend who lived a life straight from a Hollywood movie, enduring hardships and acclaim in equal measure, her music is testament to a spectacular life. Never has an artist embodied the material they performed as much as Edith Piaf; enjoy her legacy in this definitive set.','2/24/2015',1.159999999999999921,'lbs','https://media.aent-m.com/graphics/items/sdimages/c/500/8/7/6/5/2845678.jpg?ae=4621895153','Vocal');
