INSERT INTO webami_products VALUES(182105,'illmatic import|nas|nas|lp','Illmatic [Import]','Nas','Nas','LP','COLB4759591.1','5099747595912',19.39000000000000056,19.39000000000000056,'13073763','2026-11-10 23:55:47','2026-11-10 23:55:47','/509974759591','(Germany - Import)',0,'Import - Nas burst right out of the box with a classic: his 1994 Columbia debut, which teamed him with Q-Tip, DJ Premier, Large Professor and Pete Rock. The absolutely killer beats they contributed back Nas''s swaggering, street-tough rhymes; this album was the epicenter of NYC rap in ''94 and it sounds every bit as raw and powerful today: "N.Y. State of Mind," "Halftime," "It Ain''t Hard to Tell," "Represent," "One Time 4 Your Mind," "One Love," "Life''s a Bitch" and more. Import vinyl pressing! Columbia Europe.','4/15/1994',0.5,'lb','https://media.aent-m.com/graphics/items/sdimages/a/500/2/8/5/3/1133582.jpg?ae=4621895153','Rap/Hip Hop');
INSERT INTO webami_products VALUES(182106,'live import|ac dc|ac dc|lp','Live [Import]','AC/DC','AC/DC','LP','SNUK5128361.1','5099751283614',30.96000000000000085,30.96000000000000085,'14448386','2026-11-10 23:55:47','2026-11-10 23:55:47','/509975128361','(180 Gram Vinyl, Germany - Import)',0,'Digitally remastered European double vinyl LP pressing of this 1992 release from the Australian Hard Rockers, reissued to coincide with their 2008 studio release and world tour. 14 tracks. Sony/BMG.','5/26/2009',1.320000000000000062,'lbs','https://media.aent-m.com/graphics/items/sdimages/b/500/5/6/6/9/1419665.jpg?ae=4621895153','Heavy Metal,Australian');
