INSERT INTO webami_products VALUES(182386,'prelude to ecstasy|last dinner party|last dinner party|lp','Prelude To Ecstasy [Explicit Content]','Last Dinner Party','Last Dinner Party','LP','ISL144955.1','602458519082',26.96000000000000085,26.96000000000000085,'44180942','2026-11-10 23:56:02','2026-11-10 23:56:02','/60245851908','(Parental Advisory Explicit Lyrics, Colored Vinyl, Limited Edition)',0,'"Prelude To Ecstasy is a pendulum which swings between the extremes of human emotion - from the ecstasy of passion to the sublimity of pain - and it is this concept which binds our album together. This is an archeology of ourselves; you can exhume our collective and individual experiences and influences from within it''s fabric. We exorcised guitars for their solos, laid bare confessions directly from diary pages, and summoned an orchestra to bring our vision to life. It is out greatest honour and pride to present this offering to the world, it is everything we are." - The Last Dinner Party. Available on Marble vinyl.','3/22/2024',0.6400000000000000133,'lb','https://mediacdn.aent-m.com/prod-img/500/62/4302662-3122201.jpg?ae=4621895153','Rock');
INSERT INTO webami_products VALUES(182387,'prelude to ecstasy|last dinner party|last dinner party|lp','Prelude To Ecstasy','Last Dinner Party','Last Dinner Party','LP','ISL141479.1','602458519037',23.25,23.25,'44012908','2026-11-10 23:56:02','2026-11-10 23:56:02','/60245851903',NULL,0,'"Prelude To Ecstasy is a pendulum which swings between the extremes of human emotion - from the ecstasy of passion to the sublimity of pain - and it is this concept which binds our album together. This is an archeology of ourselves; you can exhume our collective and individual experiences and influences from within it''s fabric. We exorcised guitars for their solos, laid bare confessions directly from diary pages, and summoned an orchestra to bring our vision to life. It is out greatest honour and pride to present this offering to the world, it is everything we are." - The Last Dinner Party','2/2/2024',0.6300000000000000044,'lb','https://mediacdn.aent-m.com/prod-img/500/05/4275605-3080414.jpg?ae=4621895153','Rock');
INSERT INTO webami_products VALUES(182388,'guts|olivia rodrigo|olivia rodrigo|cd','Guts [Explicit Content]','Olivia Rodrigo','Olivia Rodrigo','CD','GEF5816372.2','602458163728',11.64000000000000056,11.64000000000000056,'43633128','2026-11-10 23:56:02','2026-11-10 23:56:02','/60245816372','(Parental Advisory Explicit Lyrics)',0,'2023 album from three-time Grammy award-winning recording artist Olivia Rodrigo. Guts was recorded with producer Daniel Nigro, who also collaborated with her on Sour, her chart-topping, 4x platinum debut album. "For me, this album is about growing pains and about trying to figure out who I am at this point in my life and exactly what I want to say in my songs."','9/8/2023',0.2399999999999999912,'lb','https://mediacdn.aent-m.com/prod-img/500/61/4230561-3015475.jpg?ae=4621895153','Vocal');
