INSERT INTO webami_products VALUES(182404,'stick season green colored vinyl import|noah kahan|noah kahan|lp','Stick Season - Green Colored Vinyl [Import]','Noah Kahan','Noah Kahan','LP','ISLU6504924.1','602465049244',53.34000000000000341,53.34000000000000341,'45098222','2026-11-10 23:56:03','2026-11-10 23:56:03','/60246504924','(Colored Vinyl, Green, United Kingdom - Import)',0,'Noah Kahan''s acclaimed third studio album, Stick Season, released as a limited edition green opaque double LP vinyl record. The album is a folk-infused pop record featuring raw, honest lyrics about mental health struggles, an attachment to his New England roots, and the complexities of love and loss.','2/16/2024',1.25,'lbs','https://mediacdn.aent-m.com/prod-img/500/23/4419323-3478538.jpg?ae=4621895153','Rock');
