INSERT INTO webami_products VALUES(182556,'classic love|kurt vile|kurt vile|lp','Classic Love','Kurt Vile','Kurt Vile','LP','VRVF177381.1','602478292699',13.33999999999999986,13.33999999999999986,'45258336','2026-11-10 23:56:12','2026-11-10 23:56:12','/60247829269','(Extended Play)',0,'Kurt Vile - "Classic Love". A new collaboration EP from Kurt Vile and Luke Roberts on 12" vinyl. Philly''s constant hitmaker, critical darling, and songwriter/guitarist/multi-instrumentalist Kurt Vile, returns with his upcoming collaborative EP with Nashville songsmith Luke Roberts, "Classic Love." Kurt and Luke were admirers of one another after meeting on MySpace years ago, and this release highlights both of their distinctive musical styles. "classic love" was written by Luke, "hit of the highlife" by Kurt, "slow talkers ''22" is a re-work from Kurt''s 2008 debut album and "wildflower" is a Beach House cover.','7/25/2025',0.5200000000000000177,'lb','https://mediacdn.aent-m.com/prod-img/500/86/4433686-3414768.jpg?ae=4621895153','Rock');
