INSERT INTO webami_products VALUES(182613,'reading writing and arithmetic|the sundays|the sundays|lp','Reading Writing And Arithmetic','The Sundays','The Sundays','LP','GEF190501.1','602478707339',21.10000000000000143,21.10000000000000143,'45448485','2026-11-10 23:56:14','2026-11-10 23:56:14','/60247870733',NULL,0,'The Sundays - "Reading, Writing And Arithmetic". The Sundays superb debut album", released in January 1990", is often ranked as one of the best albums of the decade. Featuring standout tracks like", "Can''t Be Sure"," "You''re Not The Only One I Know"," "I Kicked A Boy"," and "Here''s Where The Story Ends"," which topped the Billboard Alternative Airplay chart.','9/26/2025',0.5100000000000000088,'lb','https://mediacdn.aent-m.com/prod-img/500/30/4451130-3456172.jpg?ae=4621895153','Rock');
