INSERT INTO webami_products VALUES(182627,'fear|nf|nf|lp','FEAR','Nf','Nf','LP','NFRL196920.1','602478792632',20.60999999999999944,20.60999999999999944,'45765230','2026-11-10 23:56:15','2026-11-10 23:56:15','/60247879263','(Extended Play)',0,'Nf''s second EP, FEAR was released on November 14, 2025. Featuring a collaboration with James Arthur, and produced by Nf and Jeff Sojka, the EP features pop, hip-hop, and cinematic elements, of which are evident in tracks such as "HOME, " "WASHED UP, " and "SORRY." Black Vinyl','1/23/2026',0.4899999999999999912,'lb','https://mediacdn.aent-m.com/prod-img/500/64/4477764-3510328.jpg?ae=4621895153','Rap/Hip Hop');
