INSERT INTO webami_products VALUES(183117,'balance expanded edition|van halen|van halen|lp','Balance (Expanded Edition)','Van Halen','Van Halen','LP','RHI727470.1','603497816248',29.08999999999999986,29.08999999999999986,'45337420','2026-11-10 23:56:36','2026-11-10 23:56:36','/60349781624',NULL,0,'Double vinyl LP pressing. Balance (Expanded Edition) features Van Halen''s multi-platinum 10th studio album with remastered audio across 2 LPs for improved sound quality, and an exclusive vinyl etching on Side D. Contains the singles "Don''t Tell Me (What Love Can Do)," "Can''t Stop Lovin'' You" and "Amsterdam," plus the instrumental "Baluchitherium," included on the album''s vinyl format for the first time since the original 1995 release.','8/15/2025',1.020000000000000017,'lbs','https://mediacdn.aent-m.com/prod-img/500/06/4440906-3418114.jpg?ae=4621895153','Rock');
