INSERT INTO webami_products VALUES(183200,'shed|title fight|title fight|cd','Shed','Title Fight','Title Fight','CD','USOD1441.2','603967144123',11.0,11.0,'15699206','2026-11-10 23:56:42','2026-11-10 23:56:42','/60396714412','(Digipack Packaging)',1,'SHED sees the band implementing various subgenres that range from old-school hardcore to aggressive punk rock that make these twelve energetic anthems instant classics for a new generation of listeners searching for music that inspires them as much as Title Fight were inspired by their heroes. This highly anticipated debut full-length was produced by Gorilla Biscuits/ Quicksand guitarist Walter Schreifels.','5/3/2011',0.2000000000000000111,'lb','https://media.aent-m.com/graphics/items/sdimages/c/500/9/1/7/8/1818719.jpg?ae=4621895153','Alternative Rock');
