INSERT INTO webami_products VALUES(183207,'i love my computer import|ninajirachi|ninajirachi|lp','I Love My Computer [Import]','Ninajirachi','Ninajirachi','LP','IMT7501797.1','604675017976',43.64000000000000056,43.64000000000000056,'45590603','2026-11-10 23:56:42','2026-11-10 23:56:42','/60467501797','(Australia - Import)',0,'I Love My Computer is the debut studio album by Australian electronic DJ and producer Ninajirachi. It''s a nostalgic exploration of the electronic music Ninajirachi grew up listening to, including trance, electro house, and complextro.','11/7/2025',0.8800000000000000044,'lb','https://mediacdn.aent-m.com/prod-img/500/66/4463966-3468024.jpg?ae=4621895153','Rock');
