INSERT INTO webami_products VALUES(183409,'heaven or las vegas|cocteau twins|cocteau twins|lp','Heaven or Las Vegas','Cocteau Twins','Cocteau Twins','LP','FOUR73420.1','652637342017',20.51999999999999958,20.51999999999999958,'26553870','2026-11-10 23:56:54','2026-11-10 23:56:54','/65263734201','(180 Gram Vinyl, Digital Download Card)',0,'180g vinyl cut of the Scottish rock group''s sixth album from the HD masters. Includes MP3 download coupon.','9/16/2014',0.6199999999999999956,'lb','https://media.aent-m.com/graphics/items/sdimages/a/500/2/1/0/6/2576012.jpg?ae=4621895153','Rock');
