INSERT INTO webami_products VALUES(183886,'ghost in the shell original motion picture soundtrack|kenji kawai|kenji kawai|lp','Ghost in the Shell (Original Motion Picture Soundtrack)','Kenji Kawai','Kenji Kawai','LP','WRWF17.1','7640153366719',20.96999999999999887,20.96999999999999887,'32664652','2026-11-10 23:57:21','2026-11-10 23:57:21','/764015336671',NULL,0,'Vinyl LP pressing. We Release Whatever The F*** We Want Records present the ∩¼ürst ever official vinyl pressing of the soundtrack for Mamoru Oshii''s critically acclaimed and all around legendary science fiction anime film Ghost In The Shell (1995), adapted from Masamune Shirow''s groundbreaking manga series of the same name. The haunting score is composed by Kenji Kawai, one of Japan''s most celebrated soundtrack composers alongside Joe Hisaishi and Ryuichi Sakamoto, whose work includes Hideo Nakata''s Ring (1998) and Ring 2 (1999), Death Note (2006), Hong Kong ∩¼ülms Seven Swords by Tsui Hark (2005) and Ip Man by Wilson Yip (2008), and countless others.','7/14/2017',0.4199999999999999845,'lb','https://media.aent-m.com/graphics/items/sdimages/a/500/3/9/3/1/3591393.jpg?ae=4621895153','Soundtrack');
