INSERT INTO webami_products VALUES(183903,'what of our nature|haley heynderickx|haley heynderickx|lp','What Of Our Nature','Haley Heynderickx','Haley Heynderickx','LP','FAPO18851.1','767981188515',20.85000000000000143,20.85000000000000143,'45615405','2026-11-10 23:57:23','2026-11-10 23:57:23','/76798118851',NULL,0,'Vinyl LP pressing. Sophomore album from indie-Folk icon, Haley Heynderickx, and rising singer-songwriter, Max Garcia Conover.','11/21/2025',0.5699999999999999512,'lb','https://mediacdn.aent-m.com/prod-img/500/82/4466082-3466285.jpg?ae=4621895153','Folk');
