INSERT INTO webami_products VALUES(184136,'complete collapse|sleeping with sirens|sleeping with sirens|lp','Complete Collapse','Sleeping with Sirens','Sleeping with Sirens','LP','SUMR167665.1','810016766506',15.49000000000000021,15.49000000000000021,'42983644','2026-11-10 23:57:40','2026-11-10 23:57:40','/81001676650','(Clear Vinyl, Yellow, Orange)',0,'Limited translucent yellow and orange colored vinyl LP pressing. 2022 release. Complete Collapse is the 6th studio album from post-hardcore trailblazers, Sleeping with Sirens. In good company with features from Underoath''s Spencer Chamberlain, Royal & The Serpent, Dorothy, and Charlotte Sands, the band calls this release their "hardest hitting album to date."','10/14/2022',0.7199999999999999734,'lb','https://mediacdn.aent-m.com/prod-img/500/30/4132930-2878954.jpg?ae=4621895153','Rock');
