INSERT INTO webami_products VALUES(184192,'live unplugged|bad omens|bad omens|lp','Live + Unplugged','Bad Omens','Bad Omens','LP','SUMR1772645.1','810121772645',19.0,19.0,'43639618','2026-11-10 23:57:44','2026-11-10 23:57:44','/81012177264','(Colored Vinyl, Green, Violet)',0,'Limited mint green galaxy and neon violet colored vinyl LP pressing. Includes digital download. Originally released as a 2021 Record Store Day exclusive, this brand new pressing of Live + Unplugged features a wide-spine jacket with two full-color sleeves.','8/18/2023',0.969999999999999974,'lb','https://mediacdn.aent-m.com/prod-img/500/40/4231340-3602417.jpg?ae=4621895153','Rock');
