INSERT INTO webami_products VALUES(184524,'so many lovely things live in brecon|kenny barron|kenny barron|lp','So Many Lovely Things: Live in Brecon','Kenny Barron','Kenny Barron','LP','EMMQ5990564.1','8435395505366',30.98000000000000042,30.98000000000000042,'46159458','2026-11-10 23:58:05','2026-11-10 23:58:05','/843539550536','(Deluxe Edition, Limited Edition)',0,'ELEMENTAL MUSIC PRESENTS THE Kenny Barron TRIO LIVE AT THE BRECON JAZZ FESTIVAL, WALES, 1995, A NEVER-BEFORE ISSUED CONCERT RECORDING BY THE NEA JAZZ MASTER FEATURING TEN KINETIC, THINK-AS-ONE PERFORMANCES BY BARRON, BASSIST RAY DRUMMOND AND DRUMMER BEN RILEY. Limited Edition 2-LP Set from Elemental Records, produced by "Jazz Detective" Zev Feldman, with liner notes by jazz journalist/historian Ted Panken.','6/26/2026',1.100000000000000089,'lbs','https://mediacdn.aent-m.com/prod-img/500/91/4507991-3564198.jpg?ae=4621895153','Jazz');
INSERT INTO webami_products VALUES(184525,'caamp|caamp|caamp|lp','Caamp','Caamp','Caamp','LP','CAAM1.1','843563122075',16.10000000000000143,16.10000000000000143,'43718382','2026-11-10 23:58:05','2026-11-10 23:58:05','/84356312207',NULL,0,'Vinyl LP pressing. This is the vinyl pressing of Caamp''s debut, self-titled release from 2016. (Originally released on Square Roots Records.) Track Listing Side A All the Debts I Owe Vagabond Great Heights So Long, Honey Iffy Misty Side B Down the River There She Goes See the World Mockingbird Song John Henry Ohio I Keep Going.','9/15/2023',0.4899999999999999912,'lb','https://mediacdn.aent-m.com/prod-img/500/04/4241104-3173990.jpg?ae=4621895153','Rock');
