INSERT INTO webami_products VALUES(184552,'summer death|marietta|marietta|lp','Summer Death [Explicit Content]','Marietta','Marietta','LP','RFCR123C1.1','843563191385',16.19999999999999929,16.19999999999999929,'45422577','2026-11-10 23:58:06','2026-11-10 23:58:06','/84356319138','(Parental Advisory Explicit Lyrics, Colored Vinyl)',0,'Summer Death is the beloved and celebrated debut album from Philadelphia''s emo/punk darlings, Marietta. Out of print for the past few years, this tenth pressing of the cult classic marks the first time it''s been widely available to independent retail.','10/3/2025',0.5500000000000000444,'lb','https://mediacdn.aent-m.com/prod-img/500/55/4449055-3430378.jpg?ae=4621895153','Rock');
