INSERT INTO webami_products VALUES(184558,'pilot orange white twister|hot mulligan|hot mulligan|lp','Pilot - Orange & White Twister','Hot Mulligan','Hot Mulligan','LP','WXGQ25OW.1','843563193204',16.10000000000000143,16.10000000000000143,'45333125','2026-11-10 23:58:07','2026-11-10 23:58:07','/84356319320','(Colored Vinyl, Orange, White)',0,'Orange and White Twister Vinyl. Hot Mulligan''s sophomore album, Pilot, released in March 2018. Featuring fan-fave track "How Do You Know It''s Not Armadillo Shells?" Hot Mulligan is the #1 Hot New Band.','11/14/2025',0.660000000000000031,'lb','https://mediacdn.aent-m.com/prod-img/500/80/4440480-3610842.jpg?ae=4621895153','Rock');
