INSERT INTO webami_products VALUES(184722,'anti|rihanna|rihanna|cd','Anti [Explicit Content]','Rihanna','Rihanna','CD','DEFB002299302.2','851365006103',12.10999999999999944,12.10999999999999944,'30157613','2026-11-10 23:58:17','2026-11-10 23:58:17','/85136500610','(Parental Advisory Explicit Lyrics)',0,'2016 release, the eighth studio album by the R&B superstar. The album features production and/or musical assistance from Scum, Boi-1da, Jeff Bhasker, Hit-Boy, Travis Scott, Kuk Harrell, Drake, SZA and many others. Includes the single ''Work''.','2/5/2016',0.2700000000000000177,'lb','https://media.aent-m.com/graphics/items/sdimages/b/500/4/5/9/5/3075954.jpg?ae=4621895153','Soul/R & B');
INSERT INTO webami_products VALUES(184723,'the first time|kelsea ballerini|kelsea ballerini|lp','The First Time','Kelsea Ballerini','Kelsea Ballerini','LP','BLRI2015.1','851491003151',16.07999999999999829,16.07999999999999829,'28877479','2026-11-10 23:58:17','2026-11-10 23:58:17','/85149100315',NULL,0,'Vinyl LP pressing. Hailing from Knoxville, TN, Singer/Songwriter Kelsea Ballerini moved to Nashville, TN at age 15 to chase the dream of becoming a songwriter. At age 19, Kelsea signed a publishing deal with Black River publishing in 2013. Later that year, Kelsea signed a record deal with Black River Entertainment and her single ''Love Me like You Mean It'' from her debut album, The First Time','11/27/2015',0.5100000000000000088,'lb','https://media.aent-m.com/graphics/items/sdimages/b/500/4/9/8/2/3002894.jpg?ae=4621895153','Country');
