INSERT INTO webami_products VALUES(184948,'thank you purple colored vinyl import|mike d|mike d|lp','Thank You - Purple Colored Vinyl [Import]','Mike D','Mike D','LP','FFRN6105498.1','881061054986',38.78999999999999915,38.78999999999999915,'46364470','2026-11-10 23:58:34','2026-11-10 23:58:34','/88106105498','(Colored Vinyl, Purple, United Kingdom - Import)',0,'Mike D releases his debut album "Thank You", marking the first full album of new music from a Beastie Boys alumnus since 2011. Tracing it''s origins to a series of low-pressure, experimental recording sessions in Mike''s home studio, the album features a dozen sonically inventive post-electronic grooves and hypnotic hooks, with Mike D''s distinctive voice guiding the listener through a sonic playground that defies categorization.','9/4/2026',0.7199999999999999734,'lb','https://mediacdn.aent-m.com/prod-img/500/66/4522166-3623982.jpg?ae=4621895153','Rap/Hip Hop');
