INSERT INTO webami_products VALUES(185335,'hell bent forever tribute to judas priest various artists|various artists|various artists|lp','HELL BENT FOREVER - Tribute to Judas Priest (Various Artists)','Various Artists','Various Artists','LP','CLE5499.1','889466549915',17.48999999999999843,17.48999999999999843,'44195823','2026-11-10 23:58:55','2026-11-10 23:58:55','/88946654991','(Colored Vinyl, Silver)',0,'Revamped version of this 2008 all-star tribute album featuring the likes of Vince Neil (of M├╢tley Cr├╝e), Sepultura, Mot├╢rhead, Sepultura, Warrant, L.A. Guns, Fozzy (featuring Chris Jericho) and many more! Features stellar covers of Priest''s best loved songs such as "Breaking The Law," "Hell Bent For Leather," "Turbo Lover," "You''ve Got Another Thing Coming," "Living After Midnight" and more!','5/31/2024',0.4899999999999999912,'lb','https://mediacdn.aent-m.com/prod-img/500/70/4304370-3134972.jpg?ae=4621895153','Rock,Heavy Metal');
