INSERT INTO webami_products VALUES(185495,'stand alone iex|morgan wallen|morgan wallen|lp','Stand Alone (IEX)','Morgan Wallen','Morgan Wallen','LP','MHED78900.1','840526519385',18.80000000000000071,18.80000000000000071,'46633378','2026-11-21 16:08:49','2026-11-21 16:08:49','/84052651938','(Indie Exclusive, Colored Vinyl, Reissue)',0,'Citrus Vinyl. Stand Alone is the debut EP from American country-pop singer Morgan Wallen, featuring double platinum track "Spin You Around". Stand Alone was originally released in August 2015, and Wallen has since grown to tour the world, top the Billboard charts, his latest album inspiring The New York Times to proclaim Wallen as "one of the biggest stars in pop, period."','12/4/2026',0.5500000000000000444,'lb','https://webami.aent.com/content/img/no_image_CD_lrg.gif','Country');
