PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE app_config (
        id                       INTEGER PRIMARY KEY CHECK (id = 1),
        shopify_api_version      TEXT    DEFAULT '2025-01',
        shopify_location_id      TEXT,
        shopify_upc_ns           TEXT    DEFAULT 'custom',
        shopify_upc_key          TEXT    DEFAULT 'upc',
        shopify_genres_ns        TEXT    DEFAULT 'custom',
        shopify_genres_key       TEXT    DEFAULT 'genres',
        shopify_type_ns          TEXT    DEFAULT 'custom',
        shopify_type_key         TEXT    DEFAULT 'type',
        shopify_description_ns   TEXT    DEFAULT 'custom',
        shopify_description_key  TEXT    DEFAULT 'description',
        shopify_release_date_ns  TEXT    DEFAULT 'custom',
        shopify_release_date_key TEXT    DEFAULT 'release_date',
        shopify_variant_tags_ns  TEXT    DEFAULT 'custom',
        shopify_variant_tags_key TEXT    DEFAULT 'variant_tags',
        last_shopify_sync        TEXT,
        dry_run                  INTEGER DEFAULT 0,
        page_size                INTEGER DEFAULT 50,
        created_at               TEXT    DEFAULT (datetime('now')),
        updated_at               TEXT    DEFAULT (datetime('now'))
    );
CREATE TABLE shopify_products (
        product_id    TEXT PRIMARY KEY,
        title         TEXT,
        vendor        TEXT,
        status        TEXT,
        product_type  TEXT,
        tags          TEXT,
        handle        TEXT,
        category_id   TEXT,
        category_name TEXT,
        genres        TEXT,
        type          TEXT,
        upc           TEXT,
        last_synced   TEXT DEFAULT (datetime('now'))
    , release_date TEXT);
CREATE TABLE shopify_images (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        product_id  TEXT NOT NULL REFERENCES shopify_products(product_id) ON DELETE CASCADE,
        media_id    TEXT NOT NULL,
        url         TEXT,
        position    INTEGER DEFAULT 0,
        UNIQUE(product_id, media_id)
    );
CREATE TABLE sync_log (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        action     TEXT NOT NULL,
        status     TEXT NOT NULL,
        details    TEXT,
        created_at TEXT DEFAULT (datetime('now'))
    , seconds REAL);
CREATE TABLE IF NOT EXISTS "shopify_variants" (
        variant_id          TEXT PRIMARY KEY,
        product_id          TEXT NOT NULL REFERENCES shopify_products(product_id) ON DELETE CASCADE,
        title               TEXT,
        upc                 TEXT,
        description         TEXT,
        release_date        TEXT,
        variant_tags        TEXT,
        price               TEXT,
        cost                TEXT,
        media_id            TEXT,
        taxable             INTEGER DEFAULT 1,
        inventory_item_id   TEXT,
        inventory_quantity  INTEGER DEFAULT 0,
        weight              REAL,
        weight_unit         TEXT
    , barcode TEXT);
CREATE TABLE webami_orders (
        guid         TEXT PRIMARY KEY,
        number       TEXT NOT NULL,
        name         TEXT,
        submitted_at TEXT,
        sku_count    INTEGER DEFAULT 0,
        last_synced  TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE webami_order_items (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        order_guid TEXT NOT NULL REFERENCES webami_orders(guid) ON DELETE CASCADE,
        position   INTEGER NOT NULL,
        upc        TEXT,
        title      TEXT,
        artist     TEXT,
        quantity   INTEGER DEFAULT 0,
        price      REAL, sku TEXT, href TEXT, format TEXT, product_id INTEGER REFERENCES webami_products(id),
        UNIQUE(order_guid, position)
    );
CREATE TABLE webami_products (
        id           INTEGER PRIMARY KEY AUTOINCREMENT,
        fingerprint  TEXT,
        title        TEXT,
        artist       TEXT,
        vendor       TEXT,
        product_type TEXT,
        sku          TEXT,
        upc          TEXT,
        price        REAL,
        your_price   REAL,
        wmsid        TEXT,
        created_at   TEXT DEFAULT (datetime('now')),
        last_synced  TEXT DEFAULT (datetime('now'))
    , href TEXT, features TEXT, stale INTEGER DEFAULT 0, description TEXT, release_date TEXT, weight REAL, weight_unit TEXT, image_url TEXT, genres TEXT);
CREATE TABLE webami_product_ids (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        product_id INTEGER NOT NULL REFERENCES webami_products(id) ON DELETE CASCADE,
        kind       TEXT NOT NULL,
        value      TEXT NOT NULL,
        first_seen TEXT DEFAULT (datetime('now')),
        last_seen  TEXT DEFAULT (datetime('now')),
        UNIQUE(kind, value)
    );
CREATE TABLE upc_ignored (
        product_id TEXT PRIMARY KEY,
        created_at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE price_checks (
        variant_id    TEXT PRIMARY KEY,
        upc           TEXT,
        wm_upc        TEXT,
        wm_title      TEXT,
        new_cost      REAL,
        status        TEXT NOT NULL,
        suggest_upc   TEXT,
        suggest_title TEXT,
        checked_at    TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE price_queue (
        variant_id TEXT PRIMARY KEY,
        new_price  REAL NOT NULL
    );
CREATE TABLE artist_aliases (
        alias_norm TEXT PRIMARY KEY,
        alias      TEXT NOT NULL,
        canonical  TEXT NOT NULL
    );
CREATE TABLE mismatch_ignored (
        vendor_key TEXT NOT NULL,
        artist_key TEXT NOT NULL,
        PRIMARY KEY (vendor_key, artist_key)
    );
CREATE TABLE receipts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    order_guid TEXT NOT NULL, upc TEXT NOT NULL, qty INTEGER NOT NULL,
    variant_id TEXT, created_at TEXT DEFAULT (datetime('now'))
, reversed_at TEXT);
CREATE TABLE receipt_queue (
    order_guid TEXT NOT NULL, upc TEXT NOT NULL, qty INTEGER NOT NULL, action TEXT, variant_id TEXT, product_id TEXT,
    PRIMARY KEY (order_guid, upc)
);
CREATE TABLE missing_queue (
        kind TEXT NOT NULL, id TEXT NOT NULL, field TEXT NOT NULL, value TEXT,
        PRIMARY KEY (kind, id, field)
    );
CREATE TABLE missing_review (
        kind TEXT NOT NULL, id TEXT NOT NULL, PRIMARY KEY (kind, id)
    );
CREATE VIEW shopify_upcs AS
        SELECT upc, product_id, NULL AS variant_id, 'product' AS source
          FROM shopify_products WHERE upc IS NOT NULL AND upc != ''
        UNION ALL
        SELECT upc, product_id, variant_id, 'variant'
          FROM shopify_variants WHERE upc IS NOT NULL AND upc != '';
CREATE INDEX idx_products_title    ON shopify_products(title);
CREATE INDEX idx_images_product    ON shopify_images(product_id);
CREATE INDEX idx_variants_product  ON shopify_variants(product_id);
CREATE INDEX idx_variants_upc      ON shopify_variants(upc);
CREATE INDEX idx_webami_items_order   ON webami_order_items(order_guid);
CREATE INDEX idx_webami_items_upc     ON webami_order_items(upc);
CREATE INDEX idx_webami_products_fp  ON webami_products(fingerprint);
CREATE INDEX idx_webami_ids_product  ON webami_product_ids(product_id);
CREATE INDEX idx_webami_items_prod   ON webami_order_items(product_id);
CREATE INDEX idx_price_checks_status ON price_checks(status);
CREATE INDEX idx_receipts_order ON receipts(order_guid, upc);
CREATE INDEX idx_products_upc         ON shopify_products(upc);
COMMIT;
